### **Q5: C Program to Accept a String and Display:**
**(a) Length of the string**  
**(b) Total number of characters in the string**

```c
#include <stdio.h>

int main() {
    char str[100];  // Array to store the string (max 99 characters + null terminator)
    int length = 0; // Variable to hold length of string

    printf("Enter a string: ");
    fgets(str, sizeof(str), stdin); // Read string with spaces

    // Loop through each character until null character is found
    while (str[length] != '\0') {
        length++;
    }

    // Since fgets stores newline before '\0', we subtract 1 if '\n' is present
    if (str[length - 1] == '\n') {
        length--; // Don't count the newline character
    }

    printf("Length of the string: %d\n", length);
    printf("Total number of characters: %d\n", length); // Same as above unless whitespace excluded
    return 0;
}
```

