### **Q6: C Program to Accept a String and Display:**
**(a) Total number of vowels in the string**  
**(b) Copy one string into another (without using `strcpy`)**

```c
#include <stdio.h>

int main() {
    char str1[100], str2[100]; // str1 for input, str2 for copy
    int i = 0, vowels = 0;

    printf("Enter a string: ");
    fgets(str1, sizeof(str1), stdin); // Read input with spaces

    // Count vowels and copy string
    while (str1[i] != '\0') {
        // Convert uppercase to lowercase temporarily for vowel check
        char ch = str1[i];
        if (ch >= 'A' && ch <= 'Z') {
            ch += 32; // Convert to lowercase
        }

        // Check if character is a vowel
        if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u') {
            vowels++;
        }

        // Copy each character to str2
        str2[i] = str1[i];
        i++;
    }

    // Add null character at the end of copied string
    str2[i] = '\0';

    printf("Total number of vowels: %d\n", vowels);
    printf("Copied string: %s", str2); // str2 contains copy of str1

    return 0;
}
```

