### **Q6: Using Built-in Functions**
**(a) Total number of vowels in the string**  
**(b) Copy one string into the other**

```c
#include <stdio.h>
#include <string.h>  // For strcpy()

int main() {
    char str1[100], str2[100];
    int i, vowels = 0;

    printf("Enter a string: ");
    fgets(str1, sizeof(str1), stdin);

    // Remove newline if present
    str1[strcspn(str1, "\n")] = '\0';

    // Count vowels using a loop
    for (i = 0; i < strlen(str1); i++) {
        char ch = str1[i];
        if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u' ||
            ch == 'A' || ch == 'E' || ch == 'I' || ch == 'O' || ch == 'U') {
            vowels++;
        }
    }

    // Use strcpy to copy string
    strcpy(str2, str1);

    printf("Total number of vowels: %d\n", vowels);
    printf("Copied string: %s\n", str2);

    return 0;
}
```

**Explanation:**
- `fgets` is used for safe input (with spaces).
- `strcspn()` is used to strip the newline.
- `strcpy()` copies the content of `str1` into `str2`.

