#include <string.h>

int main() {
    char str[100];

    printf("Enter a string: ");
    fgets(str, sizeof(str), stdin); // Reads input with spaces

    // Manually remove newline character if present
    int len = strlen(str);
    if (str[len - 1] == '\n') {
        str[len - 1] = '\0';  // Replace newline with null terminator
    }

    printf("Length of the string: %lu\n", strlen(str));
    printf("Total number of characters in the string: %lu\n", strlen(str));

    return 0;
}
```

